def get_running_at(log, time):
    running = {}
    for row in log:
        t = int(row['time'])
        if t > time:
            break
        task = row['task']
        event = row['event']
        if event == 'start':
            running[task] = row['machine']
        elif event == 'finish' or event == 'fail' or event == 'evict':
            if task in running:
                del running[task]
    return running

