def simulate(tasks_to_exclude=None):
    if tasks_to_exclude is None:
        tasks_to_exclude = set()

    # Load data
    node_log = node_by_title(doc, "Cell window 12: Task log")
    log_rows = table_rows(node_log)
    node_mach = node_by_title(doc, "Cell window 12: Machines")
    mach_rows = table_rows(node_mach)

    machines = {}
    for idx, row in mach_rows:
        machines[row['machine']] = {
            'cpu': int(row['CPU']), 
            'mem': int(row['memory']), 
            'fail': int(row['fails at']) if row['fails at'] != '-' else None, 
            'return': int(row['returns at']) if row['returns at'] != '-' else None,
            'free_cpu': int(row['CPU']), 
            'free_mem': int(row['memory']), 
            'up': True, 
            'running_tasks': [] # list of (task_id, finish_time, priority, cpu, mem)
        }

    tasks = {}
    all_submit_times = set()
    for idx, row in log_rows:
        t_id = row['task']
        if t_id in tasks_to_exclude:
            continue
        if t_id not in tasks:
            tasks[t_id] = {
                'job': row['job'],
                'priority': int(row['priority']),
                'cpu': int(row['CPU']),
                'mem': int(row['memory']),
                'run_time': int(row['run time']),
                'submit': None,
                'start': None,
                'finish': None,
                'event': None
            }
        if row['event'] == 'submit':
            tasks[t_id]['submit'] = int(row['time'])
            all_submit_times.add(int(row['time']))

    # All times where something happens
    event_times = sorted(list(all_submit_times))
    for m_id, m_data in machines.items():
        if m_data['fail'] is not None: event_times.append(m_data['fail'])
        if m_data['return'] is not None: event_times.append(m_data['return'])

    # We also need to track finish times, which are dynamic
    current_time = 0
    queue = [] # tasks waiting: (priority, submit_time, task_id)

    # We only need to simulate until T100 starts or time 1200
    while current_time <= 1200:
        # 1. Finishes
        for m_id, m_data in machines.items():
            still_running = []
            for t_id, f_time, prio, cpu, mem in m_data['running_tasks']:
                if f_time <= current_time:
                    m_data['free_cpu'] += cpu
                    m_data['free_mem'] += mem
                else:
                    still_running.append((t_id, f_time, prio, cpu, mem))
            m_data['running_tasks'] = still_running

        # 2. Failures
        for m_id, m_data in machines.items():
            if m_data['fail'] == current_time:
                m_data['up'] = False
                for t_id, f_time, prio, cpu, mem in m_data['running_tasks']:
                    # Task fails and goes back to queue
                    queue.append((tasks[t_id]['priority'], tasks[t_id]['submit'], t_id))
                m_data['running_tasks'] = []
                m_data['free_cpu'] = m_data['cpu']
                m_data['free_mem'] = m_data['mem']

        # 3. Returns
        for m_id, m_data in machines.items():
            if m_data['return'] == current_time:
                m_data['up'] = True

        # 4. Submissions
        for t_id, t_data in tasks.items():
            if t_data['submit'] == current_time:
                queue.append((t_data['priority'], t_data['submit'], t_id))

        # Sort queue: higher priority first, then earlier submit, then lower task id
        # Task IDs are like T001, T002... let's strip the 'T' and convert to int
        def queue_key(item):
            return (-item[0], item[1], int(item[2][1:]))

        queue.sort(key=queue_key)

        # 5. Scheduling round
        # This is tricky because of reservations.
        # "The first task in the round that can start neither by a. nor by b. gets a reservation"

