def get_running_tasks_at_time(time, task_log, machines_info):
    # task_status: task_id -> (machine, start_time, end_time)
    task_status = {}

    for row in task_log:
        t = row['time']
        if t > time:
            break

        event = row['event']
        task = row['task']
        machine = row['machine']

        if event == 'start':
            task_status[task] = (machine, t, None)
        elif event == 'finish':
            if task in task_status:
                m, s, _ = task_status[task]
                task_status[task] = (m, s, t)
        elif event == 'evict' or event == 'fail':
            if task in task_status:
                m, s, _ = task_status[task]
                task_status[task] = (m, s, t)

    current_running = {}
    for m in machines_info:
        current_running[m] = []

    for task, (m, s, e) in task_status.items():
        if s <= time and (e is None or e > time):
            current_running[m].append(task)

    return current_running

