def count_starts(task_id, window_name):
    # Find the task log node
    node = None
    for n in doc['nodes']:
        if n['title'] == f"{window_name}: Task log":
            node = n
            break

    if not node:
        return "Node not found"

    starts = 0
    rows = node['table']['rows']
    for row in rows:
        # row: [time, task, job, priority, CPU, memory, run time, event, machine]
        if row[1] == task_id and row[7] == 'start':
            starts += 1
    return starts

