import collections

def get_tasks_on_machine(machine_id, start_time, end_time, task_log):
    tasks = []
    for row in task_log:
        time = int(row[0])
        task = row[1]
        event = row[7]
        mach = row[8]
        if mach == machine_id:
            if event == 'start' and time <= end_time:
                # Find when it finished or was evicted/failed
                finish_time = end_time
                for row2 in task_log:
                    if row2[1] == task and row2[7] in ['finish', 'evict', 'fail']:
                        finish_time = int(row2[0])
                        break
                if finish_time >= start_time:
                    tasks.append((task, time, finish_time))
    return tasks

