def simulate_until(chapter, time_limit):
    log_node = node_by_title(doc, f"{chapter}: Task log")
    rows = table_rows(log_node)

    machines_node = node_by_title(doc, f"{chapter}: Machines")
    machines_data = table_rows(machines_node)
    machines = {}
    for idx, row in machines_data:
        machines[row['machine']] = {
            'cpu_cap': int(row['CPU']),
            'mem_cap': int(row['memory']),
            'cpu_free': int(row['CPU']),
            'mem_free': int(row['memory']),
            'fails': int(row['fails at']) if row['fails at'] != '-' else None,
            'returns': int(row['returns at']) if row['returns at'] != '-' else None,
            'up': True,
            'tasks': set()
        }

    tasks_status = {} # tid: {status, machine, ...}

    # To properly simulate, we need to process events in order
    # The log is already in time order.
    for idx, row in rows:
        t = int(row['time'])
        if t > time_limit:
            break

        tid = row['task']
        event = row['event']
        mach = row['machine']

        if event == 'start':
            m = machines[mach]
            m['cpu_free'] -= int(row['CPU'])
            m['mem_free'] -= int(row['memory'])
            m['tasks'].add(tid)
        elif event == 'finish':
            # We need the task's CPU/Mem to free it
            # Let's find it in the log
            # Or we can store it in tasks_status
            pass # handled below
        elif event == 'evict' or event == 'fail':
            pass # handled below

    # Let's refine this.
    return machines

