def get_running_tasks(doc, window, time):
    log_node = node_by_title(doc, f"{window}: Task log")
    rows = table_rows(log_node)
    running = {} # machine -> list of tasks

    # To track tasks, we need to know when they start and finish
    # We can process the log in time order.

    events = []
    for row_idx, row in rows:
        events.append({
            'time': int(row['time']),
            'task': row['task'],
            'event': row['event'],
            'machine': row['machine'],
            'priority': int(row['priority']),
            'cpu': int(row['CPU']),
            'mem': int(row['memory']),
            'run_time': int(row['run time'])
        })

    # Sort events by time. Task log is already in time order.
    # The scheduling policy is complex, so the task log is the ground truth.

    machine_tasks = collections.defaultdict(set)

    for e in events:
        if e['time'] > time:
            break
        if e['event'] == 'start':
            machine_tasks[e['machine']].add(e['task'])
        elif e['event'] == 'finish':
            if e['task'] in machine_tasks[e['machine']]:
                machine_tasks[e['machine']].remove(e['task'])
        elif e['event'] == 'evict':
            if e['task'] in machine_tasks[e['machine']]:
                machine_tasks[e['machine']].remove(e['task'])
        elif e['event'] == 'fail':
            if e['task'] in machine_tasks[e['machine']]:
                machine_tasks[e['machine']].remove(e['task'])

    # Also need to consider machine failures
    # But the task log 'fail' event already handles tasks on the machine.
    # However, the machine itself might be down.

    return machine_tasks

