import collections

def get_running_tasks(doc, window, time):
    log_node = node_by_title(doc, f"{window}: Task log")
    rows = table_rows(log_node)

    # We need to track the state of machines at time 'time'
    # Task log is the ground truth.
    machine_tasks = collections.defaultdict(set)

    # The events at 'time' are processed in a specific order:
    # 1. Finishes
    # 2. Failures
    # 3. Returns
    # 4. Submissions
    # 5. Scheduling round

    # To find who is running "at time t" (after all events at time t),
    # we just process the log up to time t.

    for row_idx, row in rows:
        t = int(row['time'])
        if t > time:
            break

        task = row['task']
        event = row['event']
        machine = row['machine']

        if event == 'start':
            machine_tasks[machine].add(task)
        elif event == 'finish':
            if task in machine_tasks[machine]:
                machine_tasks[machine].remove(task)
        elif event == 'evict':
            if task in machine_tasks[machine]:
                machine_tasks[machine].remove(task)
        elif event == 'fail':
            if task in machine_tasks[machine]:
                machine_tasks[machine].remove(task)

    return machine_tasks

