def get_tasks_on_machine(window, machine_id):
    log_node = node_by_title(doc, f"{window}: Task log")
    rows = table_rows(log_node)
    tasks = {} # task_id: {cpu, mem, start, end}

    # First pass: get submit info
    submit_info = {}
    for idx, row in rows:
        if row['event'] == 'submit':
            submit_info[row['task']] = {
                'cpu': int(row['CPU']),
                'mem': int(row['memory']),
                'run_time': int(row['run time'])
            }

    for idx, row in rows:
        if row['event'] == 'start' and row['machine'] == machine_id:
            tid = row['task']
            start = int(row['time'])
            info = submit_info[tid]
            tasks[tid] = {'cpu': info['cpu'], 'mem': info['mem'], 'start': start, 'end': start + info['run_time']}
        elif row['event'] == 'evict' and row['machine'] == machine_id:
            tid = row['task']
            if tid in tasks:
                tasks[tid]['end'] = int(row['time'])
        elif row['event'] == 'fail' and row['machine'] == machine_id:
            # All tasks on this machine fail
            # This is tricky because we don't know which tasks were running
            pass

    return tasks

